using System.Collections.Concurrent;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Security.Cryptography.Pkcs;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using StackExchange.Redis;
using KKBOT.Plugins.Abstractions;
using KKBOT.Observability;
using KKBOT.Security;

namespace KKBOT.Marketplace;

/// <summary>
/// Plugin Marketplace for distribution, discovery, and monetization of KKBOT plugins.
/// Features: Signed packages, versioning, dependency resolution, revenue sharing, ratings.
/// </summary>
public sealed class PluginMarketplace : IHostedService, IDisposable
{
    private readonly ILogger<PluginMarketplace> _logger;
    private readonly MarketplaceOptions _options;
    private readonly IMetricsRegistry _metrics;
    private readonly ConnectionMultiplexer _redis;
    private readonly IDatabase _redisDb;
    private readonly MarketplaceDbContext _dbContext;
    private readonly X509Certificate2 _signingCertificate;
    private readonly ConcurrentDictionary<string, MarketplacePlugin> _pluginCache = new();
    private readonly Timer? _syncTimer;
    private readonly CancellationTokenSource _shutdownCts = new();
    private bool _disposed;

    public PluginMarketplace(
        ILogger<PluginMarketplace> logger,
        IOptions<MarketplaceOptions> options,
        IMetricsRegistry metrics)    {        _logger = logger;        _options = options.Value;        _metrics = metrics;
        _redis = ConnectionMultiplexer.Connect(_options.RedisConnectionString);        _redisDb = _redis.GetDatabase();
        var dbOptions = new DbContextOptionsBuilder<MarketplaceDbContext>()            .UseNpgsql(_options.PostgresConnectionString)            .Options;        _dbContext = new MarketplaceDbContext(dbOptions);
        // Load signing certificate        _signingCertificate = LoadSigningCertificate();
        _dbContext.Database.EnsureCreated();
        if (_options.EnableAutoSync)        {            _syncTimer = new Timer(                SyncWithRemoteAsync,                 null,                 TimeSpan.FromMinutes(_options.SyncIntervalMinutes),                TimeSpan.FromMinutes(_options.SyncIntervalMinutes));        }    }
    public async Task StartAsync(CancellationToken cancellationToken)    {        _logger.LogInformation("Plugin Marketplace started");        await LoadPluginCacheAsync(cancellationToken);    }
    public async Task StopAsync(CancellationToken cancellationToken)    {        _logger.LogInformation("Plugin Marketplace stopping");        _shutdownCts.Cancel();        _syncTimer?.Dispose();        await _redis.CloseAsync();        await _dbContext.DisposeAsync();        _signingCertificate.Dispose();    }
    /// <summary>    /// Publishes a new plugin version.    /// </summary>    public async Task<PublishResult> PublishPluginAsync(        string publisherId,         PluginPackage package,         CancellationToken ct = default)    {        var stopwatch = Stopwatch.StartNew();
        try        {            // Validate package            var validation = ValidatePackage(package);            if (!validation.IsValid)            {                return new PublishResult                 {                     Success = false,                     Errors = validation.Errors                 };            }
            // Check publisher permissions            var publisher = await GetPublisherAsync(publisherId, ct);            if (publisher == null || !publisher.IsVerified)            {                return new PublishResult                 {                     Success = false,                     Errors = new[] { "Publisher not verified" }                 };            }
            // Sign package            var signedPackage = await SignPackageAsync(package, publisherId, ct);
            // Store package            await StorePackageAsync(signedPackage, ct);
            // Update search index            await UpdateSearchIndexAsync(signedPackage, ct);
            // Notify subscribers            await NotifySubscribersAsync(signedPackage, ct);
            stopwatch.Stop();            _metrics.RecordHttpRequestDuration("marketplace_publish", stopwatch.Elapsed.TotalMilliseconds);
            return new PublishResult             {                 Success = true,                 PluginId = signedPackage.Metadata.Id,                Version = signedPackage.Metadata.Version             };        }        catch (Exception ex)        {            _logger.LogError(ex, "Failed to publish plugin");            return new PublishResult             {                 Success = false,                 Errors = new[] { ex.Message }             };        }    }
    /// <summary>    /// Installs a plugin for a user.    /// </summary>    public async Task<InstallResult> InstallPluginAsync(        string userId,         string pluginId,         string version = "latest",         CancellationToken ct = default)    {        var plugin = await GetPluginAsync(pluginId, version, ct);        if (plugin == null)        {            return new InstallResult { Success = false, Errors = new[] { "Plugin not found" } };        }
        // Check compatibility        var compat = CheckCompatibility(plugin);        if (!compat.IsCompatible)        {            return new InstallResult { Success = false, Errors = compat.Errors };        }
        // Check license        var license = await CheckLicenseAsync(userId, plugin, ct);        if (!license.IsValid)        {            return new InstallResult { Success = false, Errors = license.Errors };        }
        // Resolve dependencies        var dependencies = await ResolveDependenciesAsync(plugin, ct);        foreach (var dep in dependencies)        {            await InstallPluginAsync(userId, dep.PluginId, dep.Version, ct);        }
        // Download and verify        var downloadResult = await DownloadAndVerifyAsync(plugin, ct);        if (!downloadResult.Success)        {            return downloadResult;        }
        // Record installation        await RecordInstallationAsync(userId, plugin, ct);
        return new InstallResult         {             Success = true,             PluginPath = downloadResult.PluginPath,            Dependencies = dependencies.Select(d => d.PluginId).ToArray()        };    }
    /// <summary>    /// Searches for plugins.    /// </summary>    public async Task<SearchResult> SearchPluginsAsync(PluginSearchQuery query, CancellationToken ct = default)    {        var stopwatch = Stopwatch.StartNew();
        try        {            // Try Redis cache first            var cacheKey = $"search:{System.Text.Json.JsonSerializer.Serialize(query)}";            var cached = await _redisDb.StringGetAsync(cacheKey);            if (cached.HasValue)            {                var result = System.Text.Json.JsonSerializer.Deserialize<SearchResult>(cached!);                return result!;            }
            // Query database            var dbQuery = _dbContext.Plugins.AsQueryable();
            if (!string.IsNullOrWhiteSpace(query.Keyword))            {                var keyword = query.Keyword.ToLower();                dbQuery = dbQuery.Where(p => p.Name.ToLower().Contains(keyword)                     || p.Description.ToLower().Contains(keyword)                    || p.Tags.Any(t => t.ToLower().Contains(keyword)));            }            if (query.Category.HasValue)            {                dbQuery = dbQuery.Where(p => p.Category == query.Category.Value);            }            if (query.MinRating.HasValue)            {                dbQuery = dbQuery.Where(p => p.AverageRating >= query.MinRating.Value);            }            if (query.PriceType.HasValue)            {                dbQuery = dbQuery.Where(p => p.PriceType == query.PriceType.Value);            }            if (query.VerifiedOnly)            {                dbQuery = dbQuery.Where(p => p.PublisherVerified);            }
            var total = await dbQuery.CountAsync(ct);            var plugins = await dbQuery                .OrderByDescending(p => p.AverageRating)                .ThenByDescending(p => p.DownloadCount)                .Skip(query.Offset)                .Take(query.Limit)                .ToListAsync(ct);
            var result = new SearchResult            {                Plugins = plugins.Select(MapToPluginSummary).ToArray(),                TotalCount = total,                Offset = query.Offset,                Limit = query.Limit            };            // Cache results            var json = System.Text.Json.JsonSerializer.Serialize(result);            await _redisDb.StringSetAsync(cacheKey, json, TimeSpan.FromMinutes(5));            stopwatch.Stop();            return result;        }        catch (Exception ex)        {            _logger.LogError(ex, "Search failed");            return new SearchResult { Plugins = Array.Empty<PluginSummary>(), TotalCount = 0 };        }    }
    /// <summary>    /// Gets plugin details.    /// </summary>    public async Task<MarketplacePlugin?> GetPluginAsync(string pluginId, string version = "latest", CancellationToken ct = default)    {        var cacheKey = $"plugin:{pluginId}:{version}";        if (_pluginCache.TryGetValue(cacheKey, out var cached))        {            return cached;        }
        var plugin = await _dbContext.Plugins            .Include(p => p.Versions)            .FirstOrDefaultAsync(p => p.Id == pluginId, ct);
        if (plugin == null) return null;
        var targetVersion = plugin.Versions            .Where(v => version == "latest" || v.Version == version)            .OrderByDescending(v => v.PublishedAt)            .FirstOrDefault();        if (targetVersion == null) return null;        var marketplacePlugin = new MarketplacePlugin        {            Metadata = MapToPluginMetadata(plugin, targetVersion),            Publisher = await GetPublisherAsync(targetVersion.PublisherId, ct),            Changelog = targetVersion.Changelog,            Readme = targetVersion.Readme,            License = targetVersion.License,            DownloadUrl = $"{_options.CdnBaseUrl}/plugins/{pluginId}/{targetVersion.Version}/package.nupkg",            Signature = targetVersion.Signature        };        _pluginCache[cacheKey] = marketplacePlugin;        return marketplacePlugin;    }
    /// <summary>    /// Rates a plugin.    /// </summary>    public async Task<RatingResult> RatePluginAsync(string userId, string pluginId, int rating, string? review, CancellationToken ct = default)    {        if (rating < 1 || rating > 5)        {            return new RatingResult { Success = false, Errors = new[] { "Rating must be 1-5" } };        }        var hasInstalled = await _dbContext.Installations            .AnyAsync(i => i.UserId == userId && i.PluginId == pluginId, ct);        if (!hasInstalled)        {            return new RatingResult { Success = false, Errors = new[] { "Must install plugin before rating" } };        }        var existing = await _dbContext.Ratings            .FirstOrDefaultAsync(r => r.UserId == userId && r.PluginId == pluginId, ct);        if (existing != null)        {            existing.Rating = rating;            existing.Review = review;            existing.UpdatedAt = DateTimeOffset.UtcNow;        }        else        {            _dbContext.Ratings.Add(new RatingEntity            {                UserId = userId,                PluginId = pluginId,                Rating = rating,                Review = review,                CreatedAt = DateTimeOffset.UtcNow            });        }        await _dbContext.SaveChangesAsync(ct);        await UpdateAggregateRatingAsync(pluginId, ct);        return new RatingResult { Success = true };    }
    /// <summary>    /// Gets plugin analytics.    /// </summary>    public async Task<PluginAnalytics> GetAnalyticsAsync(string pluginId, string publisherId, CancellationToken ct = default)    {        var plugin = await _dbContext.Plugins.FirstOrDefaultAsync(p => p.Id == pluginId, ct);        if (plugin == null || plugin.PublisherId != publisherId)        {            throw new UnauthorizedAccessException("Not plugin owner");        }        var installations = await _dbContext.Installations            .Where(i => i.PluginId == pluginId)            .ToListAsync(ct);        var ratings = await _dbContext.Ratings            .Where(r => r.PluginId == pluginId)            .ToListAsync(ct);        var revenue = await _dbContext.Purchases            .Where(p => p.PluginId == pluginId)            .SumAsync(p => p.Amount, ct);        return new PluginAnalytics        {            PluginId = pluginId,            TotalInstallations = installations.Count,            ActiveInstallations = installations.Count(i => i.IsActive),            TotalRevenue = revenue,            AverageRating = ratings.Any() ? ratings.Average(r => r.Rating) : 0,            RatingCount = ratings.Count,            InstallationsByVersion = installations.GroupBy(i => i.Version).ToDictionary(g => g.Key, g => g.Count()),            InstallationsByDate = installations.GroupBy(i => i.InstalledAt.Date).ToDictionary(g => g.Key, g => g.Count()),            RevenueByDate = (await _dbContext.Purchases                .Where(p => p.PluginId == pluginId)                .GroupBy(p => p.PurchasedAt.Date)                .Select(g => new { Date = g.Key, Amount = g.Sum(p => p.Amount) })                .ToListAsync(ct))                .ToDictionary(x => x.Date, x => x.Amount)        };    }
    private async Task LoadPluginCacheAsync(CancellationToken ct)    {        var plugins = await _dbContext.Plugins            .Include(p => p.Versions)            .ToListAsync(ct);        foreach (var plugin in plugins)        {            var latest = plugin.Versions.OrderByDescending(v => v.PublishedAt).FirstOrDefault();            if (latest != null)            {                var key = $"plugin:{plugin.Id}:latest";                _pluginCache[key] = new MarketplacePlugin                {                    Metadata = MapToPluginMetadata(plugin, latest),                    DownloadUrl = $"{_options.CdnBaseUrl}/plugins/{plugin.Id}/{latest.Version}/package.nupkg"                };            }        }        _logger.LogInformation("Cached {Count} plugins", _pluginCache.Count);    }
    private async void SyncWithRemoteAsync(object? state)    {        if (_shutdownCts.Token.IsCancellationRequested) return;        try        {            _logger.LogDebug("Syncing with remote marketplace");        }        catch (Exception ex)        {            _logger.LogError(ex, "Remote sync failed");        }    }
    // HELPER METHODS    private PackageValidationResult ValidatePackage(PluginPackage package)    {        var errors = new List<string>();        if (string.IsNullOrWhiteSpace(package.Metadata.Id)) errors.Add("Plugin ID is required");        if (string.IsNullOrWhiteSpace(package.Metadata.Name)) errors.Add("Plugin name is required");        if (string.IsNullOrWhiteSpace(package.Metadata.Version)) errors.Add("Version is required");        if (!Version.TryParse(package.Metadata.Version, out _)) errors.Add("Invalid version format");        if (package.Assemblies == null || package.Assemblies.Length == 0) errors.Add("At least one assembly required");        foreach (var asm in package.Assemblies)        {            if (!VerifyAssemblySignature(asm)) errors.Add($"Assembly {asm.Name} has invalid signature");        }        return new PackageValidationResult { IsValid = errors.Count == 0, Errors = errors.ToArray() };    }
    private bool VerifyAssemblySignature(AssemblyPackage asm)    {        try        {            var assembly = System.Reflection.Assembly.Load(asm.Content);            return assembly.GetName().GetPublicKey().Length > 0;        }        catch { return false; }    }
    private async Task<PluginPackage> SignPackageAsync(PluginPackage package, string publisherId, CancellationToken ct)    {        var metadataJson = System.Text.Json.JsonSerializer.Serialize(package.Metadata);        var metadataHash = SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(metadataJson));        var signature = SignData(metadataHash, _signingCertificate);        return new PluginPackage        {            Metadata = package.Metadata,            Assemblies = package.Assemblies,            Dependencies = package.Dependencies,            Signature = Convert.ToBase64String(signature),            SignedAt = DateTimeOffset.UtcNow,            SignedBy = publisherId        };    }
    private byte[] SignData(byte[] data, X509Certificate2 certificate)    {        using var rsa = certificate.GetRSAPrivateKey();        return rsa.SignData(data, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);    }
    private async Task StorePackageAsync(PluginPackage package, CancellationToken ct)    {        var pluginEntity = await _dbContext.Plugins            .Include(p => p.Versions)            .FirstOrDefaultAsync(p => p.Id == package.Metadata.Id, ct);        if (pluginEntity == null)        {            pluginEntity = new PluginEntity            {                Id = package.Metadata.Id,                Name = package.Metadata.Name,                Description = package.Metadata.Description,                Category = package.Metadata.Category,                Tags = package.Metadata.Tags,                PublisherId = package.SignedBy,                CreatedAt = DateTimeOffset.UtcNow            };            _dbContext.Plugins.Add(pluginEntity);        }        var versionEntity = new PluginVersionEntity        {            PluginId = package.Metadata.Id,            Version = package.Metadata.Version,            Changelog = package.Metadata.Changelog,            Readme = package.Metadata.Readme,            License = package.Metadata.License,            PriceType = package.Metadata.PriceType,            Price = package.Metadata.Price,            Signature = package.Signature,            SignedBy = package.SignedBy,            SignedAt = package.SignedAt,            PublishedAt = DateTimeOffset.UtcNow,            MinEngineVersion = package.Metadata.MinEngineVersion,            Dependencies = System.Text.Json.JsonSerializer.Serialize(package.Dependencies)        };        pluginEntity.Versions.Add(versionEntity);        await _dbContext.SaveChangesAsync(ct);    }
    private async Task UpdateSearchIndexAsync(PluginPackage package, CancellationToken ct)    {        var indexKey = $"search:plugin:{package.Metadata.Id}";        var searchDoc = new { id = package.Metadata.Id, name = package.Metadata.Name, description = package.Metadata.Description, category = package.Metadata.Category.ToString(), tags = package.Metadata.Tags, rating = 0.0, downloads = 0, priceType = package.Metadata.PriceType.ToString(), updated = DateTimeOffset.UtcNow.ToString("O") };        var json = System.Text.Json.JsonSerializer.Serialize(searchDoc);        await _redisDb.StringSetAsync(indexKey, json);    }
    private async Task NotifySubscribersAsync(PluginPackage package, CancellationToken ct)    {        var subscribers = await _dbContext.Subscriptions            .Where(s => s.PluginId == package.Metadata.Id && s.NotifyOnUpdate)            .ToListAsync(ct);        foreach (var sub in subscribers)        {            _logger.LogDebug("Notifying subscriber {UserId} about update to {PluginId}", sub.UserId, package.Metadata.Id);        }    }
    private CompatibilityResult CheckCompatibility(MarketplacePlugin plugin)    {        var errors = new List<string>();        if (!Version.TryParse(plugin.Metadata.MinEngineVersion, out var minVersion))            errors.Add("Invalid minimum engine version");        else if (Version.Parse("24.1.0") < minVersion)            errors.Add($"Requires engine version {minVersion} or higher");        return new CompatibilityResult { IsCompatible = errors.Count == 0, Errors = errors.ToArray() };    }
    private async Task<LicenseCheckResult> CheckLicenseAsync(string userId, MarketplacePlugin plugin, CancellationToken ct)    {        var pluginEntity = await _dbContext.Plugins.Include(p => p.Versions).FirstOrDefaultAsync(p => p.Id == plugin.Metadata.Id, ct);        if (pluginEntity?.PriceType == PriceType.Free) return new LicenseCheckResult { IsValid = true };        var purchase = await _dbContext.Purchases.FirstOrDefaultAsync(p => p.UserId == userId && p.PluginId == plugin.Metadata.Id, ct);        if (purchase == null) return new LicenseCheckResult { IsValid = false, Errors = new[] { "License required" } };        return new LicenseCheckResult { IsValid = true };    }
    private async Task<DependencyResolutionResult[]> ResolveDependenciesAsync(MarketplacePlugin plugin, CancellationToken ct)    {        var results = new List<DependencyResolutionResult>();        foreach (var dep in plugin.Metadata.Dependencies)        {            var depPlugin = await GetPluginAsync(dep.PluginId, dep.Version, ct);            if (depPlugin != null)                results.Add(new DependencyResolutionResult { PluginId = dep.PluginId, Version = dep.Version, Resolved = true });            else                results.Add(new DependencyResolutionResult { PluginId = dep.PluginId, Version = dep.Version, Resolved = false, Error = "Dependency not found" });        }        return results.ToArray();    }
    private async Task<DownloadResult> DownloadAndVerifyAsync(MarketplacePlugin plugin, CancellationToken ct)    {        return new DownloadResult { Success = true, PluginPath = "/tmp/plugin.dll" };    }
    private async Task RecordInstallationAsync(string userId, MarketplacePlugin plugin, CancellationToken ct)    {        var installation = new InstallationEntity        {            UserId = userId,            PluginId = plugin.Metadata.Id,            Version = plugin.Metadata.Version,            InstalledAt = DateTimeOffset.UtcNow,            IsActive = true        };        _dbContext.Installations.Add(installation);        await _dbContext.SaveChangesAsync(ct);    }
    private async Task UpdateAggregateRatingAsync(string pluginId, CancellationToken ct)    {        var avgRating = await _dbContext.Ratings.Where(r => r.PluginId == pluginId).AverageAsync(r => (double?)r.Rating, ct) ?? 0;        var plugin = await _dbContext.Plugins.FirstOrDefaultAsync(p => p.Id == pluginId, ct);        if (plugin != null)        {            plugin.AverageRating = (decimal)avgRating;            plugin.RatingCount = await _dbContext.Ratings.CountAsync(r => r.PluginId == pluginId, ct);            await _dbContext.SaveChangesAsync(ct);        }    }
    private X509Certificate2 LoadSigningCertificate()    {        if (File.Exists(_options.SigningCertificatePath))            return new X509Certificate2(_options.SigningCertificatePath, _options.SigningCertificatePassword);        return CreateSelfSignedCertificate();    }
    private X509Certificate2 CreateSelfSignedCertificate()    {        var distinguishedName = new X500DistinguishedName("CN=KKBOT Marketplace");        using var rsa = RSA.Create(2048);        var request = new CertificateRequest(distinguishedName, rsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);        request.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.DigitalSignature, true));        request.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(new OidCollection { new Oid("1.3.6.1.5.5.7.3.3") }, false));        return request.CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddYears(10));    }
    private PluginMetadata MapToPluginMetadata(PluginEntity plugin, PluginVersionEntity version)    {        return new PluginMetadata        {            Id = plugin.Id,            Name = plugin.Name,            Version = version.Version,            Description = plugin.Description,            Category = plugin.Category,            Tags = plugin.Tags,            Author = plugin.PublisherId,            MinEngineVersion = version.MinEngineVersion,            Dependencies = System.Text.Json.JsonSerializer.Deserialize<PluginDependency[]>(version.Dependencies) ?? Array.Empty<PluginDependency()>(),            PriceType = version.PriceType,            Price = version.Price,            Changelog = version.Changelog,            Readme = version.Readme        };    }
    private PluginSummary MapToPluginSummary(PluginEntity plugin)    {        var latest = plugin.Versions.OrderByDescending(v => v.PublishedAt).FirstOrDefault();        return new PluginSummary        {            Id = plugin.Id,            Name = plugin.Name,            Description = plugin.Description,            Category = plugin.Category,            Tags = plugin.Tags,            LatestVersion = latest?.Version ?? "0.0.0",            AverageRating = plugin.AverageRating,            DownloadCount = plugin.DownloadCount,            PriceType = latest?.PriceType ?? PriceType.Free,            Price = latest?.Price ?? 0,            PublisherVerified = plugin.PublisherVerified,            UpdatedAt = latest?.PublishedAt ?? plugin.CreatedAt        };    }
    private async Task<Publisher?> GetPublisherAsync(string publisherId, CancellationToken ct)    {        var pub = await _dbContext.Publishers.FirstOrDefaultAsync(p => p.Id == publisherId, ct);        if (pub == null) return null;        return new Publisher { Id = pub.Id, Name = pub.Name, Email = pub.Email, IsVerified = pub.IsVerified, RevenueSharePercent = pub.RevenueSharePercent };    }
    public void Dispose()    {        if (_disposed) return;        _disposed = true;        _shutdownCts.Cancel();        _redis?.Dispose();        _dbContext?.Dispose();        _signingCertificate?.Dispose();    }
}

// ==================== INTERNAL MODELS ====================
internal sealed class MarketplaceDbContext : DbContext
{    public MarketplaceDbContext(DbContextOptions<MarketplaceDbContext> options) : base(options) { }    public DbSet<PluginEntity> Plugins { get; set; }    public DbSet<PluginVersionEntity> PluginVersions { get; set; }    public DbSet<PublisherEntity> Publishers { get; set; }    public DbSet<InstallationEntity> Installations { get; set; }    public DbSet<RatingEntity> Ratings { get; set; }    public DbSet<PurchaseEntity> Purchases { get; set; }    public DbSet<SubscriptionEntity> Subscriptions { get; set; }    protected override void OnModelCreating(ModelBuilder modelBuilder)    {        modelBuilder.Entity<PluginEntity>(e => { e.HasKey(p => p.Id); e.HasIndex(p => p.Category); e.HasIndex(p => p.PublisherId); });        modelBuilder.Entity<PluginVersionEntity>(e => { e.HasKey(v => new { v.PluginId, v.Version }); e.HasIndex(v => v.PublishedAt); });        modelBuilder.Entity<PublisherEntity>(e => { e.HasKey(p => p.Id); e.HasIndex(p => p.Email).IsUnique(); });        modelBuilder.Entity<InstallationEntity>(e => { e.HasKey(i => new { i.UserId, i.PluginId, i.Version }); e.HasIndex(i => i.UserId); e.HasIndex(i => i.PluginId); });        modelBuilder.Entity<RatingEntity>(e => { e.HasKey(r => new { r.UserId, r.PluginId }); e.HasIndex(r => r.PluginId); });        modelBuilder.Entity<PurchaseEntity>(e => { e.HasKey(p => p.Id); e.HasIndex(p => p.UserId); e.HasIndex(p => p.PluginId); });    }}
internal sealed class PluginEntity { public string Id { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public string Description { get; set; } = string.Empty; public PluginCategory Category { get; set; } public string[] Tags { get; set; } = Array.Empty<string>(); public string PublisherId { get; set; } = string.Empty; public bool PublisherVerified { get; set; } public decimal AverageRating { get; set; } public int RatingCount { get; set; } public long DownloadCount { get; set; } public DateTimeOffset CreatedAt { get; set; } public DateTimeOffset UpdatedAt { get; set; } public List<PluginVersionEntity> Versions { get; set; } = new(); }
internal sealed class PluginVersionEntity { public string PluginId { get; set; } = string.Empty; public string Version { get; set; } = string.Empty; public string Changelog { get; set; } = string.Empty; public string Readme { get; set; } = string.Empty; public string License { get; set; } = string.Empty; public PriceType PriceType { get; set; } public decimal Price { get; set; } public string Signature { get; set; } = string.Empty; public string SignedBy { get; set; } = string.Empty; public DateTimeOffset SignedAt { get; set; } public DateTimeOffset PublishedAt { get; set; } public string MinEngineVersion { get; set; } = string.Empty; public string Dependencies { get; set; } = "[]"; public PluginEntity Plugin { get; set; } = null!; }
internal sealed class PublisherEntity { public string Id { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public string Email { get; set; } = string.Empty; public string PublicKey { get; set; } = string.Empty; public bool IsVerified { get; set; } public decimal RevenueSharePercent { get; set; } = 70; public DateTimeOffset CreatedAt { get; set; } }
internal sealed class InstallationEntity { public string UserId { get; set; } = string.Empty; public string PluginId { get; set; } = string.Empty; public string Version { get; set; } = string.Empty; public DateTimeOffset InstalledAt { get; set; } public bool IsActive { get; set; } = true; }
internal sealed class RatingEntity { public string UserId { get; set; } = string.Empty; public string PluginId { get; set; } = string.Empty; public int Rating { get; set; } public string Review { get; set; } = string.Empty; public DateTimeOffset CreatedAt { get; set; } public DateTimeOffset UpdatedAt { get; set; } }
internal sealed class PurchaseEntity { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string UserId { get; set; } = string.Empty; public string PluginId { get; set; } = string.Empty; public decimal Amount { get; set; } public string Currency { get; set; } = "USD"; public DateTimeOffset PurchasedAt { get; set; } }
internal sealed class SubscriptionEntity { public string UserId { get; set; } = string.Empty; public string PluginId { get; set; } = string.Empty; public bool NotifyOnUpdate { get; set; } = true; public DateTimeOffset SubscribedAt { get; set; } }

// ==================== PUBLIC MODELS ====================
public sealed class PluginPackage { public PluginMetadata Metadata { get; set; } = new(); public AssemblyPackage[] Assemblies { get; set; } = Array.Empty<AssemblyPackage>(); public PluginDependency[] Dependencies { get; set; } = Array.Empty<PluginDependency>(); public string Signature { get; set; } = string.Empty; public DateTimeOffset SignedAt { get; set; } public string SignedBy { get; set; } = string.Empty; }
public sealed class AssemblyPackage { public string Name { get; set; } = string.Empty; public byte[] Content { get; set; } = Array.Empty<byte>(); public string Checksum { get; set; } = string.Empty; }
public sealed class PluginMetadata { public string Id { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public string Version { get; set; } = string.Empty; public string Description { get; set; } = string.Empty; public PluginCategory Category { get; set; } public string[] Tags { get; set; } = Array.Empty<string>(); public string Author { get; set; } = string.Empty; public string MinEngineVersion { get; set; } = string.Empty; public PluginDependency[] Dependencies { get; set; } = Array.Empty<PluginDependency()>(); public PriceType PriceType { get; set; } = PriceType.Free; public decimal Price { get; set; } public string Changelog { get; set; } = string.Empty; public string Readme { get; set; } = string.Empty; public string License { get; set; } = string.Empty; }
public sealed class PluginDependency { public string PluginId { get; set; } = string.Empty; public string Version { get; set; } = "latest"; public bool Optional { get; set; } = false; }
public enum PluginCategory { Combat, Quest, Economy, Utility, AntiDetection, Logistics, VisualScripting, AI, Other }
public enum PriceType { Free, Paid, Subscription, Freemium }
public sealed class MarketplacePlugin { public PluginMetadata Metadata { get; set; } = new(); public Publisher? Publisher { get; set; } public string Changelog { get; set; } = string.Empty; public string Readme { get; set; } = string.Empty; public string License { get; set; } = string.Empty; public string DownloadUrl { get; set; } = string.Empty; public string Signature { get; set; } = string.Empty; }
public sealed class Publisher { public string Id { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public string Email { get; set; } = string.Empty; public bool IsVerified { get; set; } public decimal RevenueSharePercent { get; set; } }
public sealed class PluginSummary { public string Id { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public string Description { get; set; } = string.Empty; public PluginCategory Category { get; set; } public string[] Tags { get; set; } = Array.Empty<string>(); public string LatestVersion { get; set; } = string.Empty; public decimal AverageRating { get; set; } public long DownloadCount { get; set; } public PriceType PriceType { get; set; } public decimal Price { get; set; } public bool PublisherVerified { get; set; } public DateTimeOffset UpdatedAt { get; set; } }
public sealed class PluginSearchQuery { public string Keyword { get; set; } = string.Empty; public PluginCategory? Category { get; set; } public decimal? MinRating { get; set; } public PriceType? PriceType { get; set; } public bool VerifiedOnly { get; set; } = false; public int Offset { get; set; } = 0; public int Limit { get; set; } = 20; }
public sealed class SearchResult { public PluginSummary[] Plugins { get; set; } = Array.Empty<PluginSummary>(); public int TotalCount { get; set; } public int Offset { get; set; } public int Limit { get; set; } }
public sealed class PublishResult { public bool Success { get; set; } public string PluginId { get; set; } = string.Empty; public string Version { get; set; } = string.Empty; public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class InstallResult { public bool Success { get; set; } public string PluginPath { get; set; } = string.Empty; public string[] Dependencies { get; set; } = Array.Empty<string>(); public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class RatingResult { public bool Success { get; set; } public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class DownloadResult { public bool Success { get; set; } public string PluginPath { get; set; } = string.Empty; public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class PackageValidationResult { public bool IsValid { get; set; } public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class CompatibilityResult { public bool IsCompatible { get; set; } public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class LicenseCheckResult { public bool IsValid { get; set; } public string[] Errors { get; set; } = Array.Empty<string>(); }
public sealed class DependencyResolutionResult { public string PluginId { get; set; } = string.Empty; public string Version { get; set; } = string.Empty; public bool Resolved { get; set; } public string Error { get; set; } = string.Empty; }
public sealed class PluginAnalytics { public string PluginId { get; set; } = string.Empty; public int TotalInstallations { get; set; } public int ActiveInstallations { get; set; } public decimal TotalRevenue { get; set; } public double AverageRating { get; set; } public int RatingCount { get; set; } public Dictionary<string, int> InstallationsByVersion { get; set; } = new(); public Dictionary<DateTime, int> InstallationsByDate { get; set; } = new(); public Dictionary<DateTime, decimal> RevenueByDate { get; set; } = new(); }
public sealed class MarketplaceOptions { public string RedisConnectionString { get; set; } = "localhost:6379"; public string PostgresConnectionString { get; set; } = "Host=localhost;Database=kkbot_marketplace;Username=kkbot;Password=kkbot"; public string CdnBaseUrl { get; set; } = "https://cdn.kkbot.io"; public string SigningCertificatePath { get; set; } = "./certs/marketplace.pfx"; public string SigningCertificatePassword { get; set; } = ""; public bool EnableAutoSync { get; set; } = true; public int SyncIntervalMinutes { get; set; } = 60; public int CacheTtlMinutes { get; set; } = 5; }
public static class MarketplaceExtensions { public static IServiceCollection AddKkbotMarketplace(this IServiceCollection services, IConfiguration configuration) { services.Configure<MarketplaceOptions>(configuration.GetSection("Marketplace")); services.AddSingleton<PluginMarketplace>(); services.AddHostedService(sp => sp.GetRequiredService<PluginMarketplace>()); return services; } }
